CREATE SCHEMA IF NOT EXISTS industrendindia AUTHORIZATION CURRENT_USER; SET search_path TO industrendindia,pg_catalog;
CREATE TABLE IF NOT EXISTS stores(store_id uuid PRIMARY KEY,slug varchar(120) NOT NULL UNIQUE,display_name varchar(160) NOT NULL,description text,status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','ACTIVE','SUSPENDED')),configuration jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE INDEX IF NOT EXISTS stores_active_idx ON stores(status,display_name);
CREATE TABLE IF NOT EXISTS media_assets(asset_id uuid PRIMARY KEY,store_id uuid REFERENCES stores(store_id) ON DELETE CASCADE,object_key text NOT NULL UNIQUE,public_url text NOT NULL,mime_type varchar(100) NOT NULL,alt_text varchar(300),width integer CHECK(width IS NULL OR width>0),height integer CHECK(height IS NULL OR height>0),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE INDEX IF NOT EXISTS media_assets_store_idx ON media_assets(store_id);
CREATE TABLE IF NOT EXISTS categories(category_id uuid PRIMARY KEY,parent_category_id uuid REFERENCES categories(category_id),slug varchar(120) NOT NULL UNIQUE,name varchar(140) NOT NULL,sort_order integer NOT NULL DEFAULT 0,status varchar(20) NOT NULL DEFAULT 'ACTIVE',configuration jsonb NOT NULL DEFAULT '{}'::jsonb); CREATE INDEX IF NOT EXISTS categories_parent_sort_idx ON categories(parent_category_id,sort_order);
CREATE TABLE IF NOT EXISTS products(product_id uuid PRIMARY KEY,store_id uuid NOT NULL REFERENCES stores(store_id),sku varchar(100) NOT NULL,slug varchar(180) NOT NULL,name varchar(220) NOT NULL,description text,price_minor bigint NOT NULL CHECK(price_minor>=0),compare_at_price_minor bigint CHECK(compare_at_price_minor IS NULL OR compare_at_price_minor>=price_minor),currency char(3) NOT NULL DEFAULT 'INR',inventory_quantity integer NOT NULL DEFAULT 0 CHECK(inventory_quantity>=0),status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','ACTIVE','ARCHIVED')),attributes jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(store_id,sku),UNIQUE(store_id,slug)); CREATE INDEX IF NOT EXISTS products_store_status_idx ON products(store_id,status,created_at DESC); CREATE INDEX IF NOT EXISTS products_attributes_gin ON products USING gin(attributes);
CREATE TABLE IF NOT EXISTS product_categories(product_id uuid NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,category_id uuid NOT NULL REFERENCES categories(category_id) ON DELETE CASCADE,PRIMARY KEY(product_id,category_id)); CREATE INDEX IF NOT EXISTS product_categories_category_idx ON product_categories(category_id,product_id);
CREATE TABLE IF NOT EXISTS product_media(product_id uuid NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,asset_id uuid NOT NULL REFERENCES media_assets(asset_id) ON DELETE CASCADE,sort_order integer NOT NULL DEFAULT 0,PRIMARY KEY(product_id,asset_id));
CREATE TABLE IF NOT EXISTS site_content(content_key varchar(160) PRIMARY KEY,locale varchar(20) NOT NULL DEFAULT 'en-IN',content jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PUBLISHED','ARCHIVED')),version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_by text NOT NULL DEFAULT current_user); CREATE INDEX IF NOT EXISTS site_content_status_locale_idx ON site_content(status,locale); CREATE INDEX IF NOT EXISTS site_content_gin ON site_content USING gin(content);
